# -*- coding: utf-8 -*-
# Studi Kasus Koding HTML (bahasa "web"): halaman dirender di iframe, tiap tes = (deskripsi, ekspresi JS).
# Helper ekspresi di browser: d (document), w (window), $(sel), $$(sel) → array, gaya(sel|node, properti).

def W(id, judul, tingkat, soal, solusi, awal, tes, petunjuk, jelas, cerita="", petunjuk3=""):
    return dict(id=id, judul=judul, tingkat=tingkat, bahasa="web", soal=soal, solusi=solusi, awal=awal,
                tes=tes, petunjuk=petunjuk, jelas=jelas, cerita=cerita, petunjuk3=petunjuk3)

def dok(body, head="", judul="Latihan", lang="id"):
    return f'<!DOCTYPE html>\n<html lang="{lang}">\n<head>\n  <meta charset="utf-8">\n  <title>{judul}</title>\n{head}</head>\n<body>\n{body}\n</body>\n</html>\n'

AWAL_KOSONG = '<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\n  <!-- tulis halamanmu di sini -->\n</body>\n</html>\n'
# setiap input/select/textarea punya label (pembungkus atau label[for])
SEMUA_BERLABEL = "$$('input:not([type=submit]):not([type=hidden]),select,textarea').every(x => x.closest('label') || (x.id && $('label[for=\"' + x.id + '\"]')))"

def ujian_web(id, topik, setelah, judul, cakupan, cerita, bagian):
    langkah = []
    for n, b in enumerate(bagian):
        L_ = W(f"{id}-{'abc'[n]}", f"Bagian {'ABC'[n]}: {b['judul']}", min(3, n + 2), b["soal"], b["solusi"], b["awal"], b["tes"], b["petunjuk"], b["jelas"],
               cerita=cerita if n == 0 else f"Lanjutan bagian {'AB'[n - 1]}: halamanmu yang sudah lulus otomatis dipakai sebagai kode awal.")
        if n:
            L_["awal_baru"] = f"<!-- Bagian {'ABC'[n]}: lanjutkan halaman di atas -->\n"
        langkah.append(L_)
    studi(id=id, topik=topik, setelah=setelah, judul=judul, ujian=True, cakupan=cakupan, bahasa="web",
          contoh=dict(PANDUAN, kode=dok('  <h1>Bagian A</h1>\n  <!-- bagian B dan C menambah isi halaman yang sama -->'), penjelasan=PANDUAN["penjelasan"].replace("fungsi baru di bawahnya", "bagian baru ke halaman yang sama")),
          langkah=langkah)

# ---------------------------------------------------------------- 1. struktur
studi(id="html-struktur", topik="html", setelah="struktur", judul="Kerangka halaman pertamamu", bahasa="web",
  contoh=dict(judul="Contoh: kerangka HTML5 lengkap",
    penjelasan="<p>Setiap halaman diawali <code>&lt;!DOCTYPE html&gt;</code>, lalu <code>&lt;html lang=\"id\"&gt;</code> berisi <code>&lt;head&gt;</code> (informasi untuk browser: charset, judul tab) dan <code>&lt;body&gt;</code> (yang tampil di layar).</p>",
    kode=dok('  <h1>Halo, saya Jauza</h1>\n  <p>Saya belajar HTML.</p>', judul="Profil Jauza"),
    kunci="DOCTYPE → html lang → head (meta charset, title) → body. Hanya isi body yang tampil di halaman."),
  langkah=[
    W("html-struktur-1", "Halaman profil", 1,
      "Buat halaman lengkap: <code>&lt;!DOCTYPE html&gt;</code>, <code>&lt;html lang=\"id\"&gt;</code>, <code>&lt;meta charset=\"utf-8\"&gt;</code>, judul tab <b>Profil Saya</b>, dan sebuah <code>&lt;h1&gt;</code> berisi namamu di body.",
      dok('  <h1>Jauza Kenar Indra Fawaid</h1>', judul="Profil Saya"), AWAL_KOSONG,
      [("Ada <!DOCTYPE html>", "d.doctype && d.doctype.name === 'html'"),
       ("Tag <html> memakai lang=\"id\"", "d.documentElement.lang === 'id'"),
       ("Ada <meta charset=\"utf-8\">", "!!$('meta[charset]') && $('meta[charset]').getAttribute('charset').toLowerCase() === 'utf-8'"),
       ("Judul tab persis \"Profil Saya\"", "d.title === 'Profil Saya'"),
       ("Ada <h1> berisi teks di dalam body", "!!$('body h1') && $('body h1').textContent.trim().length > 0")],
      ["Lihat contoh terpandu: semua bagian kerangka ada di sana.", "Judul tab ditulis di <title> di dalam <head>, bukan di body."],
      "lang membantu pembaca layar dan Google; charset utf-8 membuat huruf seperti é atau emoji tampil benar."),
    W("html-struktur-2", "Halaman dua bagian", 1,
      "Buat halaman berjudul tab <b>Tentang Gleematic</b> berisi satu <code>&lt;h1&gt;</code>, lalu <b>dua</b> <code>&lt;h2&gt;</code> (misalnya Visi dan Layanan) yang masing-masing diikuti minimal satu paragraf <code>&lt;p&gt;</code>. Tambahkan juga satu komentar HTML.",
      dok('  <h1>Tentang Gleematic</h1>\n  <!-- dua bagian utama -->\n  <h2>Visi</h2>\n  <p>Otomasi pekerjaan rutin dengan AI dan RPA.</p>\n  <h2>Layanan</h2>\n  <p>Robot perangkat lunak dan integrasi ERP.</p>', judul="Tentang Gleematic"),
      dok('  <!-- tulis di sini -->', judul=""),
      [("Judul tab \"Tentang Gleematic\"", "d.title === 'Tentang Gleematic'"),
       ("Tepat satu <h1>", "$$('h1').length === 1"),
       ("Ada dua <h2>", "$$('h2').length === 2"),
       ("Setiap <h2> langsung diikuti <p>", "$$('h2').every(h => h.nextElementSibling && h.nextElementSibling.tagName === 'P')"),
       ("Ada komentar HTML <!-- ... -->", "[...d.body.childNodes].some(n => n.nodeType === 8) || /<!--/.test(d.body.innerHTML)")],
      ["Struktur yang dicek: h1, lalu h2 + p, lalu h2 + p.", "Komentar ditulis <!-- seperti ini --> dan tidak tampil di halaman."],
      "Satu h1 per halaman dan urutan heading yang rapi memudahkan pembaca layar dan mesin pencari memahami isi halaman."),
  ])

# ---------------------------------------------------------------- 2. teks
studi(id="html-teks", topik="html", setelah="teks", judul="Teks, heading, dan daftar", bahasa="web",
  contoh=dict(judul="Contoh: ul, ol, strong, em",
    penjelasan="<p><code>&lt;ul&gt;</code> = daftar berpoin (urutan tidak penting), <code>&lt;ol&gt;</code> = daftar bernomor (urutan penting). Setiap butir memakai <code>&lt;li&gt;</code>. <code>&lt;strong&gt;</code> menandai teks penting, <code>&lt;em&gt;</code> memberi penekanan.</p>",
    kode=dok('  <h2>Belanja</h2>\n  <ul>\n    <li>Kopi</li>\n    <li>Gula</li>\n  </ul>\n  <h2>Cara membuat</h2>\n  <ol>\n    <li>Rebus air</li>\n    <li>Seduh <strong>2 sendok</strong> kopi, <em>jangan</em> terlalu panas</li>\n  </ol>'),
    kunci="ul untuk poin, ol untuk langkah berurutan. li hanya boleh menjadi anak langsung ul/ol."),
  langkah=[
    W("html-teks-1", "Daftar belanja", 1,
      "Buat <code>&lt;h2&gt;</code> \"Daftar Belanja\" lalu <code>&lt;ul&gt;</code> berisi minimal <b>3</b> <code>&lt;li&gt;</code>.",
      dok('  <h2>Daftar Belanja</h2>\n  <ul>\n    <li>Kopi</li>\n    <li>Gula</li>\n    <li>Susu</li>\n  </ul>'), dok('  <!-- tulis di sini -->'),
      [("Ada <h2> berisi \"Daftar Belanja\"", "!!$('h2') && $('h2').textContent.trim() === 'Daftar Belanja'"),
       ("Ada <ul> dengan minimal 3 <li>", "!!$('ul') && $('ul').querySelectorAll(':scope > li').length >= 3"),
       ("Semua <li> berisi teks", "$$('li').every(li => li.textContent.trim())")],
      ["Struktur: <ul> lalu beberapa <li> di dalamnya.", "Pastikan setiap <li> ditutup </li>."],
      "Daftar dengan ul/li dibaca pembaca layar sebagai 'daftar, 3 item', jauh lebih jelas daripada baris teks dengan tanda minus."),
    W("html-teks-2", "Halaman resep", 2,
      "Buat resep: <code>&lt;h1&gt;</code> nama masakan, <code>&lt;h2&gt;</code> \"Bahan\" diikuti <code>&lt;ul&gt;</code> (≥ 3 item), <code>&lt;h2&gt;</code> \"Langkah\" diikuti <code>&lt;ol&gt;</code> (≥ 3 item). Di salah satu langkah gunakan <code>&lt;strong&gt;</code> dan di langkah lain <code>&lt;em&gt;</code>.",
      dok('  <h1>Nasi Goreng</h1>\n  <h2>Bahan</h2>\n  <ul>\n    <li>Nasi</li>\n    <li>Telur</li>\n    <li>Kecap</li>\n  </ul>\n  <h2>Langkah</h2>\n  <ol>\n    <li>Panaskan <strong>2 sendok</strong> minyak</li>\n    <li>Masukkan telur, <em>aduk cepat</em></li>\n    <li>Tambahkan nasi dan kecap</li>\n  </ol>'), dok('  <!-- tulis di sini -->'),
      [("Ada satu <h1>", "$$('h1').length === 1"),
       ("<h2> \"Bahan\" diikuti <ul> berisi ≥ 3 item", "$$('h2').some(h => h.textContent.trim() === 'Bahan' && h.nextElementSibling && h.nextElementSibling.tagName === 'UL' && h.nextElementSibling.children.length >= 3)"),
       ("<h2> \"Langkah\" diikuti <ol> berisi ≥ 3 item", "$$('h2').some(h => h.textContent.trim() === 'Langkah' && h.nextElementSibling && h.nextElementSibling.tagName === 'OL' && h.nextElementSibling.children.length >= 3)"),
       ("Ada <strong> di dalam langkah", "!!$('ol li strong')"),
       ("Ada <em> di dalam langkah", "!!$('ol li em')")],
      ["Bahan tidak berurutan → ul. Langkah berurutan → ol.", "strong dan em ditaruh DI DALAM li, misalnya <li>Panaskan <strong>2 sendok</strong> minyak</li>."],
      "Memilih ul atau ol berdasarkan makna (berurutan atau tidak) adalah inti HTML semantik."),
  ])

# ---------------------------------------------------------------- 3. media
studi(id="html-media", topik="html", setelah="media", judul="Link, gambar, dan figure", bahasa="web",
  contoh=dict(judul="Contoh: a, img, figure",
    penjelasan="<p><code>&lt;a href&gt;</code> membuat link; <code>target=\"_blank\"</code> membuka tab baru dan sebaiknya disertai <code>rel=\"noopener\"</code>. <code>&lt;img&gt;</code> wajib punya <code>alt</code> (teks pengganti). Link ke bagian halaman memakai <code>href=\"#id\"</code>.</p>",
    kode=dok('  <a href="#kontak">Ke kontak</a>\n  <figure>\n    <img src="https://picsum.photos/200/120" alt="Pemandangan gunung" width="200">\n    <figcaption>Foto contoh</figcaption>\n  </figure>\n  <p><a href="https://www.odoo.com" target="_blank" rel="noopener">Situs Odoo</a></p>\n  <h2 id="kontak">Kontak</h2>'),
    kunci="img selalu punya alt. Link tab baru: target=\"_blank\" rel=\"noopener\". Link internal: href=\"#id\"."),
  langkah=[
    W("html-media-1", "Link keluar dan gambar", 1,
      "Buat link ke <code>https://www.odoo.com</code> yang terbuka di tab baru dengan aman (<code>rel</code> berisi <code>noopener</code>), dan sebuah <code>&lt;img&gt;</code> dengan <code>src</code> dan <code>alt</code> yang tidak kosong.",
      dok('  <a href="https://www.odoo.com" target="_blank" rel="noopener">Odoo</a>\n  <img src="logo.png" alt="Logo perusahaan">'), dok('  <!-- tulis di sini -->'),
      [("Ada link ke https://www.odoo.com", "!!$('a[href^=\"https://www.odoo.com\"]')"),
       ("Link terbuka di tab baru (target=\"_blank\")", "!!$('a[target=\"_blank\"]')"),
       ("Link tab baru memakai rel=\"noopener\"", "$$('a[target=\"_blank\"]').length > 0 && $$('a[target=\"_blank\"]').every(a => /noopener/.test(a.rel))"),
       ("Ada <img> dengan src", "!!$('img[src]') && $('img').getAttribute('src').trim() !== ''"),
       ("Semua gambar punya alt yang tidak kosong", "$$('img').length > 0 && $$('img').every(i => (i.getAttribute('alt') || '').trim())")],
      ["Atribut a: href, target, rel.", "alt menjelaskan isi gambar, misalnya alt=\"Logo perusahaan\"."],
      "Tanpa rel=\"noopener\", halaman yang dibuka bisa mengakses window.opener halamanmu (celah keamanan tabnabbing)."),
    W("html-media-2", "Galeri dan navigasi halaman", 2,
      "Buat <b>dua</b> <code>&lt;figure&gt;</code>, masing-masing berisi <code>&lt;img&gt;</code> beralt dan <code>&lt;figcaption&gt;</code>. Di atasnya buat link <code>href=\"#kontak\"</code>, dan di bawah buat elemen dengan <code>id=\"kontak\"</code>.",
      dok('  <a href="#kontak">Hubungi kami</a>\n  <figure><img src="a.jpg" alt="Kantor Batam"><figcaption>Kantor</figcaption></figure>\n  <figure><img src="b.jpg" alt="Tim developer"><figcaption>Tim</figcaption></figure>\n  <h2 id="kontak">Kontak</h2>'), dok('  <!-- tulis di sini -->'),
      [("Ada 2 <figure>", "$$('figure').length === 2"),
       ("Setiap figure berisi img beralt dan figcaption", "$$('figure').every(f => f.querySelector('img') && (f.querySelector('img').getAttribute('alt') || '').trim() && f.querySelector('figcaption'))"),
       ("Ada link href=\"#kontak\"", "!!$('a[href=\"#kontak\"]')"),
       ("Ada elemen id=\"kontak\"", "!!d.getElementById('kontak')"),
       ("Link #kontak berada sebelum elemen kontak", "!!$('a[href=\"#kontak\"]') && !!d.getElementById('kontak') && !!($('a[href=\"#kontak\"]').compareDocumentPosition(d.getElementById('kontak')) & 4)")],
      ["figure membungkus img dan figcaption menjadi satu kesatuan.", "Link internal: <a href=\"#kontak\"> menuju elemen dengan id=\"kontak\"."],
      "figcaption memberi keterangan yang terhubung secara semantik ke gambar, berbeda dengan alt yang menggantikan gambar."),
  ])

# ---------------------------------------------------------------- 4. form
studi(id="html-form", topik="html", setelah="form", judul="Membuat form yang benar", bahasa="web",
  contoh=dict(judul="Contoh: label, type, required",
    penjelasan="<p>Setiap input butuh <code>&lt;label&gt;</code>: dengan <code>for</code> yang sama dengan <code>id</code> input, atau dengan membungkus input. <code>type</code> yang tepat (email, password, number) memberi keyboard dan validasi yang sesuai. <code>required</code> mewajibkan isian.</p>",
    kode=dok('  <form>\n    <label for="email">Email</label>\n    <input id="email" name="email" type="email" required>\n    <label><input type="checkbox" name="ingat"> Ingat saya</label>\n    <button type="submit">Masuk</button>\n  </form>'),
    kunci="label for=\"x\" + input id=\"x\". Pakai type yang sesuai isi. name diperlukan agar nilai ikut terkirim."),
  langkah=[
    W("html-form-1", "Form login", 1,
      "Buat <code>&lt;form&gt;</code> berisi input email (<code>type=\"email\"</code>, <code>required</code>), input password (<code>type=\"password\"</code>, <code>minlength=\"8\"</code>), keduanya punya <code>name</code> dan label, serta tombol <code>type=\"submit\"</code>.",
      dok('  <form>\n    <label for="email">Email</label>\n    <input id="email" name="email" type="email" required>\n    <label for="sandi">Password</label>\n    <input id="sandi" name="sandi" type="password" minlength="8" required>\n    <button type="submit">Masuk</button>\n  </form>'), dok('  <form>\n    <!-- tulis di sini -->\n  </form>'),
      [("Ada input type=\"email\" yang required", "!!$('form input[type=email][required]')"),
       ("Ada input type=\"password\" dengan minlength=\"8\"", "!!$('form input[type=password]') && $('form input[type=password]').getAttribute('minlength') === '8'"),
       ("Kedua input punya name", "$$('form input').length >= 2 && $$('form input').every(i => i.name)"),
       ("Setiap input punya label", SEMUA_BERLABEL),
       ("Ada tombol submit", "!!$('form button[type=submit], form input[type=submit]')")],
      ["Pasangkan label dan input: <label for=\"email\"> dengan <input id=\"email\">.", "minlength=\"8\" ditulis sebagai atribut input password."],
      "Label membuat area klik lebih besar dan dibacakan pembaca layar. name adalah kunci data saat form dikirim."),
    W("html-form-2", "Form pendaftaran lengkap", 2,
      "Form pendaftaran berisi: <code>&lt;select&gt;</code> posisi dengan ≥ 3 <code>&lt;option&gt;</code>; 2 radio button \"Laki-laki\"/\"Perempuan\" dengan <code>name</code> yang <b>sama</b>; checkbox persetujuan yang <code>required</code>; <code>&lt;textarea&gt;</code> motivasi; semua kontrol punya label; dan tombol submit.",
      dok('  <form>\n    <label for="posisi">Posisi</label>\n    <select id="posisi" name="posisi">\n      <option>Odoo Developer</option>\n      <option>Data Analyst</option>\n      <option>QA Tester</option>\n    </select>\n    <fieldset>\n      <legend>Jenis kelamin</legend>\n      <label><input type="radio" name="jk" value="L"> Laki-laki</label>\n      <label><input type="radio" name="jk" value="P"> Perempuan</label>\n    </fieldset>\n    <label for="motivasi">Motivasi</label>\n    <textarea id="motivasi" name="motivasi"></textarea>\n    <label><input type="checkbox" name="setuju" required> Saya setuju</label>\n    <button type="submit">Daftar</button>\n  </form>'), dok('  <form>\n    <!-- tulis di sini -->\n  </form>'),
      [("Ada <select> dengan ≥ 3 option", "!!$('form select') && $('form select').options.length >= 3"),
       ("Ada 2 radio dengan name yang sama", "$$('input[type=radio]').length >= 2 && new Set($$('input[type=radio]').map(r => r.name)).size === 1 && !!$('input[type=radio]').name"),
       ("Ada checkbox yang required", "!!$('input[type=checkbox][required]')"),
       ("Ada <textarea>", "!!$('form textarea')"),
       ("Setiap kontrol punya label", SEMUA_BERLABEL),
       ("Ada tombol submit", "!!$('form button[type=submit], form input[type=submit]')")],
      ["Radio dengan name sama menjadi satu grup: hanya satu yang bisa dipilih.", "Bungkus radio dan checkbox di dalam label: <label><input type=\"radio\" name=\"jk\"> Laki-laki</label>."],
      "fieldset + legend memberi judul untuk sekelompok radio, sehingga pembaca layar menyebut 'Jenis kelamin, Laki-laki'."),
  ])

# ---------------------------------------------------------------- 5. semantik
studi(id="html-semantik", topik="html", setelah="semantik", judul="Tata letak semantik", bahasa="web",
  contoh=dict(judul="Contoh: header, nav, main, article, footer",
    penjelasan="<p>Tag semantik menjelaskan <i>peran</i> bagian halaman: <code>header</code> (kepala), <code>nav</code> (navigasi utama), <code>main</code> (isi utama, satu per halaman), <code>article</code> (konten yang berdiri sendiri), <code>aside</code> (pelengkap), <code>footer</code> (kaki).</p>",
    kode=dok('  <header>\n    <h1>Blog Odoo</h1>\n    <nav><ul><li><a href="#">Beranda</a></li><li><a href="#">Tutorial</a></li></ul></nav>\n  </header>\n  <main>\n    <article>\n      <h2>Membuat modul pertama</h2>\n      <p>Diterbitkan <time datetime="2026-11-24">24 November 2026</time></p>\n    </article>\n    <aside>Artikel terkait</aside>\n  </main>\n  <footer>© 2026</footer>'),
    kunci="Satu main per halaman. nav untuk navigasi utama. time datetime memakai format mesin YYYY-MM-DD."),
  langkah=[
    W("html-sem-1", "Kerangka situs perusahaan", 1,
      "Buat struktur: <code>&lt;header&gt;</code> berisi <code>&lt;h1&gt;</code> dan <code>&lt;nav&gt;</code> (berisi <code>&lt;ul&gt;</code> dengan ≥ 3 link), lalu <b>satu</b> <code>&lt;main&gt;</code>, lalu <code>&lt;footer&gt;</code>.",
      dok('  <header>\n    <h1>Glee Trees</h1>\n    <nav>\n      <ul>\n        <li><a href="#layanan">Layanan</a></li>\n        <li><a href="#karier">Karier</a></li>\n        <li><a href="#kontak">Kontak</a></li>\n      </ul>\n    </nav>\n  </header>\n  <main>\n    <p>Isi utama</p>\n  </main>\n  <footer>© 2026 Glee Trees</footer>'), dok('  <!-- tulis di sini -->'),
      [("<header> berisi <h1>", "!!$('header h1')"),
       ("<nav> di dalam header berisi <ul> dengan ≥ 3 link", "!!$('header nav ul') && $$('header nav ul li a').length >= 3"),
       ("Tepat satu <main>", "$$('main').length === 1"),
       ("Ada <footer> setelah main", "!!$('footer') && !!$('main') && !!($('main').compareDocumentPosition($('footer')) & 4)")],
      ["Urutan: header (h1 + nav), main, footer.", "nav berisi ul > li > a."],
      "Pembaca layar bisa melompat langsung ke landmark seperti main dan nav; div tidak memberi informasi itu."),
    W("html-sem-2", "Artikel blog", 2,
      "Di dalam <code>&lt;main&gt;</code>, buat <code>&lt;article&gt;</code> berisi <code>&lt;h2&gt;</code>, elemen <code>&lt;time&gt;</code> dengan <code>datetime</code> berformat <code>YYYY-MM-DD</code>, dan minimal dua <code>&lt;section&gt;</code> yang masing-masing punya heading. Tambahkan <code>&lt;aside&gt;</code> di dalam main.",
      dok('  <main>\n    <article>\n      <h2>Modul approval Odoo</h2>\n      <p>Ditulis <time datetime="2026-11-24">24 November 2026</time></p>\n      <section><h3>Masalah</h3><p>Order besar perlu disetujui.</p></section>\n      <section><h3>Solusi</h3><p>Status Waiting Approval.</p></section>\n    </article>\n    <aside>Baca juga: modul purchase</aside>\n  </main>'), dok('  <main>\n    <!-- tulis di sini -->\n  </main>'),
      [("Ada <article> di dalam main dengan <h2>", "!!$('main article h2')"),
       ("Ada <time> dengan datetime YYYY-MM-DD", "!!$('article time[datetime]') && /^\\d{4}-\\d{2}-\\d{2}$/.test($('article time').getAttribute('datetime'))"),
       ("Ada ≥ 2 <section> di dalam article", "$$('article section').length >= 2"),
       ("Setiap section punya heading", "$$('article section').length > 0 && $$('article section').every(s => s.querySelector('h2,h3,h4'))"),
       ("Ada <aside> di dalam main", "!!$('main aside')")],
      ["article = konten mandiri; section = bagian bertema di dalamnya, masing-masing dengan heading.", "datetime ditulis untuk mesin, teks di dalam time untuk manusia: <time datetime=\"2026-11-24\">24 November 2026</time>."],
      "Struktur ini membuat artikel mudah dipahami mesin pencari dan fitur 'reader mode' browser."),
  ])

# ---------------------------------------------------------------- 6. a11y
studi(id="html-a11y", topik="html", setelah="a11y", judul="Memperbaiki aksesibilitas", bahasa="web",
  contoh=dict(judul="Contoh: dari div yang bisa diklik ke button",
    penjelasan="<p>Elemen interaktif harus elemen yang tepat: <code>&lt;button&gt;</code> untuk aksi, <code>&lt;a&gt;</code> untuk pindah halaman. <code>div</code> yang diberi onclick tidak bisa difokus keyboard dan tidak dikenali pembaca layar. Gambar butuh <code>alt</code>, input butuh label.</p>",
    kode=dok('  <!-- buruk -->\n  <div class="tombol">Kirim</div>\n  <img src="grafik.png">\n  <!-- baik -->\n  <button type="button">Kirim</button>\n  <img src="grafik.png" alt="Grafik penjualan naik 20% di November">'),
    kunci="Aksi → button. Pindah halaman → a href. Gambar informatif → alt yang menjelaskan isinya; gambar hiasan → alt=\"\"."),
  langkah=[
    W("html-a11y-1", "Perbaiki halaman yang tidak aksesibel", 2,
      "Kode awal punya <b>4 masalah</b> aksesibilitas. Perbaiki: (1) \"tombol\" div harus menjadi <code>&lt;button&gt;</code>; (2) gambar tanpa alt; (3) input tanpa label; (4) halaman tanpa <code>lang</code>. Isi teks dan gambar tetap ada.",
      dok('  <h1>Kontak</h1>\n  <img src="peta.png" alt="Peta lokasi kantor di Batam">\n  <label for="nama">Nama</label>\n  <input id="nama" name="nama">\n  <button type="button">Kirim</button>'),
      '<!DOCTYPE html>\n<html>\n<head>\n  <meta charset="utf-8">\n  <title>Latihan</title>\n</head>\n<body>\n  <h1>Kontak</h1>\n  <img src="peta.png">\n  <input id="nama" name="nama" placeholder="Nama">\n  <div class="tombol" onclick="kirim()">Kirim</div>\n</body>\n</html>\n',
      [("Halaman punya lang", "!!d.documentElement.lang"),
       ("Gambar peta punya alt yang tidak kosong", "!!$('img') && ($('img').getAttribute('alt') || '').trim().length > 0"),
       ("Input nama punya label", SEMUA_BERLABEL),
       ("Tombol Kirim memakai <button>", "$$('button').some(b => b.textContent.trim() === 'Kirim')"),
       ("Tidak ada lagi div dengan onclick", "!$('div[onclick]')")],
      ["Placeholder BUKAN pengganti label: ia hilang saat pengguna mengetik.", "Ganti <div ... onclick> dengan <button type=\"button\">Kirim</button>."],
      "Keempat masalah ini adalah temuan paling umum di audit aksesibilitas (WCAG). Memperbaikinya juga membantu SEO."),
    W("html-a11y-2", "Heading berurutan dan skip link", 2,
      "Buat halaman dengan: link \"Lewati ke konten\" sebagai elemen pertama di body (<code>href=\"#konten\"</code>), <code>&lt;main id=\"konten\"&gt;</code>, tepat satu <code>&lt;h1&gt;</code>, dan heading yang <b>tidak melompat level</b> (h1 → h2 → h3, tidak boleh h1 → h3).",
      dok('  <a href="#konten">Lewati ke konten</a>\n  <header><nav><a href="#">Beranda</a></nav></header>\n  <main id="konten">\n    <h1>Layanan</h1>\n    <h2>RPA</h2>\n    <h3>Otomasi faktur</h3>\n    <h2>ERP</h2>\n  </main>'),
      dok('  <header><nav><a href="#">Beranda</a></nav></header>\n  <main>\n    <h1>Layanan</h1>\n    <h3>RPA</h3>\n  </main>'),
      [("Elemen pertama di body adalah link ke #konten", "!!d.body.firstElementChild && d.body.firstElementChild.matches('a[href=\"#konten\"]')"),
       ("<main> punya id=\"konten\"", "!!$('main#konten')"),
       ("Tepat satu <h1>", "$$('h1').length === 1"),
       ("Level heading tidak melompat", "$$('h1,h2,h3,h4,h5,h6').every((h, i, a) => i === 0 || +h.tagName[1] - +a[i - 1].tagName[1] <= 1)"),
       ("Ada minimal satu <h2>", "$$('h2').length >= 1")],
      ["Skip link membantu pengguna keyboard melompati menu yang panjang.", "Kode awal melompat dari h1 ke h3; tambahkan h2 di antaranya."],
      "Heading adalah 'daftar isi' bagi pembaca layar. Level yang melompat membuat struktur halaman membingungkan."),
  ])

# ---------------------------------------------------------------- 7. tabel
studi(id="html-tabel", topik="html", setelah="tabel", judul="Tabel data yang lengkap", bahasa="web",
  contoh=dict(judul="Contoh: caption, thead, th scope, tfoot",
    penjelasan="<p>Tabel untuk <b>data</b> (bukan tata letak). <code>&lt;caption&gt;</code> = judul tabel, <code>&lt;thead&gt;</code>/<code>&lt;tbody&gt;</code>/<code>&lt;tfoot&gt;</code> = kepala/isi/kaki, <code>&lt;th scope=\"col\"&gt;</code> = judul kolom. <code>colspan</code>/<code>rowspan</code> menggabungkan sel.</p>",
    kode=dok('  <table border="1">\n    <caption>Penjualan November</caption>\n    <thead><tr><th scope="col">Produk</th><th scope="col">Qty</th></tr></thead>\n    <tbody><tr><td>Kopi</td><td>12</td></tr><tr><td>Teh</td><td>7</td></tr></tbody>\n    <tfoot><tr><th scope="row">Total</th><td>19</td></tr></tfoot>\n  </table>'),
    kunci="caption → thead (th scope=col) → tbody (td) → tfoot. colspan=\"2\" melebar ke 2 kolom."),
  langkah=[
    W("html-tabel-1", "Tabel nilai", 1,
      "Buat tabel dengan <code>&lt;caption&gt;</code>, <code>&lt;thead&gt;</code> berisi 3 <code>&lt;th scope=\"col\"&gt;</code> (Nama, Mata Kuliah, Nilai), dan <code>&lt;tbody&gt;</code> berisi 3 baris data.",
      dok('  <table>\n    <caption>Nilai semester</caption>\n    <thead><tr><th scope="col">Nama</th><th scope="col">Mata Kuliah</th><th scope="col">Nilai</th></tr></thead>\n    <tbody>\n      <tr><td>Ani</td><td>Basis Data</td><td>A</td></tr>\n      <tr><td>Budi</td><td>Web</td><td>B</td></tr>\n      <tr><td>Cita</td><td>ERP</td><td>A</td></tr>\n    </tbody>\n  </table>'), dok('  <!-- tulis di sini -->'),
      [("Ada <caption>", "!!$('table caption')"),
       ("thead berisi 3 th scope=\"col\"", "$$('thead th[scope=col]').length === 3"),
       ("tbody berisi 3 baris", "!!$('tbody') && $('tbody').rows.length === 3"),
       ("Setiap baris data punya 3 sel", "!!$('tbody') && [...$('tbody').rows].every(r => r.cells.length === 3)")],
      ["Mulai dari contoh terpandu, tambahkan satu kolom.", "scope=\"col\" memberi tahu bahwa th itu judul KOLOM."],
      "scope membuat pembaca layar menyebut judul kolom setiap kali membaca sel, sehingga tabel bisa dipahami tanpa melihat."),
    W("html-tabel-2", "Laporan dengan sel gabungan", 2,
      "Buat laporan penjualan per wilayah: baris kepala pertama berisi th \"Wilayah\" dengan <code>rowspan=\"2\"</code> dan th \"Penjualan\" dengan <code>colspan=\"2\"</code>; baris kepala kedua berisi th \"Q3\" dan \"Q4\"; tbody ≥ 2 wilayah; dan <code>&lt;tfoot&gt;</code> berisi baris Total.",
      dok('  <table>\n    <caption>Penjualan per wilayah</caption>\n    <thead>\n      <tr><th rowspan="2" scope="col">Wilayah</th><th colspan="2" scope="colgroup">Penjualan</th></tr>\n      <tr><th scope="col">Q3</th><th scope="col">Q4</th></tr>\n    </thead>\n    <tbody>\n      <tr><th scope="row">Batam</th><td>120</td><td>150</td></tr>\n      <tr><th scope="row">Solo</th><td>90</td><td>110</td></tr>\n    </tbody>\n    <tfoot><tr><th scope="row">Total</th><td>210</td><td>260</td></tr></tfoot>\n  </table>'), dok('  <table>\n    <!-- tulis di sini -->\n  </table>'),
      [("thead punya 2 baris", "!!$('thead') && $('thead').rows.length === 2"),
       ("th \"Wilayah\" memakai rowspan=\"2\"", "$$('thead th').some(t => t.textContent.trim() === 'Wilayah' && t.rowSpan === 2)"),
       ("th \"Penjualan\" memakai colspan=\"2\"", "$$('thead th').some(t => t.textContent.trim() === 'Penjualan' && t.colSpan === 2)"),
       ("Baris kepala kedua berisi Q3 dan Q4", "!!$('thead') && $('thead').rows.length === 2 && [...$('thead').rows[1].cells].map(c => c.textContent.trim()).join() === 'Q3,Q4'"),
       ("tbody berisi ≥ 2 wilayah", "!!$('tbody') && $('tbody').rows.length >= 2"),
       ("Ada tfoot berisi Total", "!!$('tfoot') && /Total/.test($('tfoot').textContent)")],
      ["Gambar dulu di kertas: kolom Wilayah setinggi 2 baris kepala, kolom Penjualan selebar 2 kolom.", "Baris kepala kedua hanya berisi Q3 dan Q4 karena kolom Wilayah sudah 'turun' dari baris pertama."],
      "rowspan dan colspan sering membingungkan karena sel yang 'tertutup' tidak ditulis ulang. Tabel laporan seperti ini sering muncul di template laporan QWeb Odoo."),
  ])

# ---------------------------------------------------------------- 8. head
studi(id="html-head", topik="html", setelah="head", judul="Isi <head>: SEO dan media sosial", bahasa="web",
  contoh=dict(judul="Contoh: meta yang paling penting",
    penjelasan="<p><code>viewport</code> membuat halaman pas di HP. <code>description</code> muncul di hasil Google. Meta Open Graph (<code>og:</code>) mengatur pratinjau saat link dibagikan ke WhatsApp/LinkedIn. Script sebaiknya dimuat dengan <code>defer</code>.</p>",
    kode='<!DOCTYPE html>\n<html lang="id">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <title>KodeQuiz: latihan coding</title>\n  <meta name="description" content="Latihan coding Python dan Odoo gratis.">\n  <meta property="og:title" content="KodeQuiz">\n  <link rel="icon" href="ikon.png">\n  <script src="app.js" defer></script>\n</head>\n<body><p>Lihat kode sumbernya, bukan tampilannya.</p></body>\n</html>\n',
    kunci="Meta tidak tampil di halaman, tapi menentukan tampilan di HP, Google, dan media sosial."),
  langkah=[
    W("html-head-1", "Meta dasar", 1,
      "Lengkapi <code>&lt;head&gt;</code>: meta <code>viewport</code> (<code>width=device-width, initial-scale=1</code>), <code>&lt;title&gt;</code> maksimal 60 karakter, meta <code>description</code> 50–160 karakter, dan <code>&lt;link rel=\"icon\"&gt;</code>.",
      '<!DOCTYPE html>\n<html lang="id">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <title>Jauza Fawaid | Odoo Developer</title>\n  <meta name="description" content="Portofolio Jauza Fawaid: modul Odoo 17, analisis data, dan proyek web.">\n  <link rel="icon" href="ikon.png">\n</head>\n<body><h1>Portofolio</h1></body>\n</html>\n',
      '<!DOCTYPE html>\n<html lang="id">\n<head>\n  <meta charset="utf-8">\n  <!-- lengkapi di sini -->\n</head>\n<body><h1>Portofolio</h1></body>\n</html>\n',
      [("Ada meta viewport width=device-width", "!!$('meta[name=viewport]') && /width=device-width/.test($('meta[name=viewport]').content)"),
       ("Ada title 1–60 karakter", "d.title.trim().length > 0 && d.title.length <= 60"),
       ("Meta description 50–160 karakter", "!!$('meta[name=description]') && $('meta[name=description]').content.length >= 50 && $('meta[name=description]').content.length <= 160"),
       ("Ada link rel=\"icon\"", "!!$('link[rel~=icon]')")],
      ["Semua tag ini ditaruh di dalam <head>, bukan body.", "Hitung panjang description: cukup 1–2 kalimat yang menjelaskan halaman."],
      "Tanpa meta viewport, HP menampilkan halaman versi desktop yang diperkecil. Judul lebih dari ±60 karakter dipotong di hasil Google."),
    W("html-head-2", "Pratinjau saat dibagikan", 2,
      "Tambahkan Open Graph: <code>og:title</code>, <code>og:description</code>, <code>og:image</code> (URL https), dan <code>og:type</code> bernilai <code>website</code>. Muat juga <code>style.css</code> dengan <code>&lt;link rel=\"stylesheet\"&gt;</code> dan <code>app.js</code> dengan <code>defer</code>.",
      '<!DOCTYPE html>\n<html lang="id">\n<head>\n  <meta charset="utf-8">\n  <title>Portofolio Jauza</title>\n  <meta property="og:title" content="Portofolio Jauza">\n  <meta property="og:description" content="Modul Odoo 17 dan proyek data.">\n  <meta property="og:image" content="https://contoh.com/sampul.png">\n  <meta property="og:type" content="website">\n  <link rel="stylesheet" href="style.css">\n  <script src="app.js" defer></script>\n</head>\n<body></body>\n</html>\n',
      '<!DOCTYPE html>\n<html lang="id">\n<head>\n  <meta charset="utf-8">\n  <title>Portofolio Jauza</title>\n  <!-- tulis di sini -->\n</head>\n<body></body>\n</html>\n',
      [("og:title dan og:description terisi", "['og:title', 'og:description'].every(p => $('meta[property=\"' + p + '\"]') && $('meta[property=\"' + p + '\"]').content.trim())"),
       ("og:image memakai URL https", "!!$('meta[property=\"og:image\"]') && /^https:\\/\\//.test($('meta[property=\"og:image\"]').content)"),
       ("og:type bernilai website", "!!$('meta[property=\"og:type\"]') && $('meta[property=\"og:type\"]').content === 'website'"),
       ("style.css dimuat dengan link rel=\"stylesheet\"", "!!$('link[rel=stylesheet][href=\"style.css\"]')"),
       ("app.js dimuat dengan defer", "!!$('script[src=\"app.js\"][defer]')")],
      ["Open Graph memakai atribut property, bukan name: <meta property=\"og:title\" content=\"...\">.", "defer membuat script dijalankan setelah HTML selesai dibaca, tanpa menahan tampilan."],
      "Pratinjau link yang rapi di LinkedIn/WhatsApp membuat portofolio terlihat profesional saat dibagikan ke rekruter."),
  ])

# ---------------------------------------------------------------- 9. interaktif
studi(id="html-interaktif", topik="html", setelah="interaktif", judul="Elemen interaktif tanpa JavaScript", bahasa="web",
  contoh=dict(judul="Contoh: details, progress, data-*",
    penjelasan="<p><code>&lt;details&gt;</code> + <code>&lt;summary&gt;</code> membuat bagian yang bisa dibuka-tutup tanpa JavaScript. <code>&lt;progress&gt;</code> menampilkan kemajuan, <code>&lt;meter&gt;</code> menampilkan ukuran dalam rentang. Atribut <code>data-*</code> menyimpan data untuk JavaScript.</p>",
    kode=dok('  <details open>\n    <summary>Apa itu Odoo?</summary>\n    <p>ERP open source.</p>\n  </details>\n  <label>Progres belajar <progress value="7" max="10">70%</progress></label>\n  <p><button type="button" data-produk="42">Tambah</button></p>'),
    kunci="details/summary = FAQ tanpa JS. data-nama-apa-saja=\"...\" dibaca di JS lewat element.dataset."),
  langkah=[
    W("html-int-1", "FAQ lamaran", 1,
      "Buat FAQ berisi minimal <b>3</b> <code>&lt;details&gt;</code>, masing-masing dengan <code>&lt;summary&gt;</code> berisi pertanyaan dan paragraf jawaban. Pertanyaan pertama terbuka sejak awal (<code>open</code>).",
      dok('  <h2>FAQ</h2>\n  <details open><summary>Apakah kerja onsite?</summary><p>Ya, di Batam.</p></details>\n  <details><summary>Ada coding test?</summary><p>Ada, setelah interview.</p></details>\n  <details><summary>Ada tunjangan tempat tinggal?</summary><p>Ada, untuk kandidat dari luar Batam.</p></details>'), dok('  <h2>FAQ</h2>\n  <!-- tulis di sini -->'),
      [("Ada ≥ 3 <details>", "$$('details').length >= 3"),
       ("Setiap details punya <summary> berisi teks", "$$('details').length > 0 && $$('details').every(x => x.querySelector('summary') && x.querySelector('summary').textContent.trim())"),
       ("Setiap details punya paragraf jawaban", "$$('details').length > 0 && $$('details').every(x => x.querySelector('p'))"),
       ("Hanya details pertama yang open", "$$('details').length > 0 && $$('details')[0].open && $$('details').slice(1).every(x => !x.open)")],
      ["Struktur: <details><summary>Pertanyaan</summary><p>Jawaban</p></details>.", "Atribut open tanpa nilai cukup ditulis di details pertama."],
      "details/summary sudah aksesibel (bisa dibuka dengan keyboard) tanpa satu baris JavaScript pun."),
    W("html-int-2", "Panel progres belajar", 2,
      "Buat panel berisi: <code>&lt;progress&gt;</code> dengan <code>max=\"45\"</code> dan <code>value=\"12\"</code> yang punya label; <code>&lt;meter&gt;</code> skor dengan <code>min=\"0\" max=\"100\" value=\"75\"</code>; dan minimal 2 tombol yang punya atribut <code>data-bab</code> berisi angka.",
      dok('  <label for="prog">Tantangan selesai</label>\n  <progress id="prog" max="45" value="12">12 dari 45</progress>\n  <label for="skor">Skor rata-rata</label>\n  <meter id="skor" min="0" max="100" value="75">75</meter>\n  <button type="button" data-bab="1">Bab 1</button>\n  <button type="button" data-bab="2">Bab 2</button>'), dok('  <!-- tulis di sini -->'),
      [("progress max 45 value 12", "!!$('progress') && $('progress').max === 45 && $('progress').value === 12"),
       ("progress punya label", "!!$('progress') && (!!$('progress').closest('label') || (!!$('progress').id && !!$('label[for=\"' + $('progress').id + '\"]')))"),
       ("meter min 0 max 100 value 75", "!!$('meter') && $('meter').min === 0 && $('meter').max === 100 && $('meter').value === 75"),
       ("≥ 2 tombol dengan data-bab berisi angka", "$$('button[data-bab]').length >= 2 && $$('button[data-bab]').every(b => /^\\d+$/.test(b.dataset.bab))")],
      ["progress untuk kemajuan tugas; meter untuk nilai dalam rentang (skor, kapasitas disk).", "data-bab=\"1\" dibaca di JavaScript sebagai tombol.dataset.bab."],
      "Atribut data-* adalah cara standar menyimpan informasi kecil di HTML untuk dipakai JavaScript, misalnya id produk di tombol 'Tambah'."),
  ])

# ---------------------------------------------------------------- 🏁 HTML bab 1–5
ujian_web("uji-html-1", "html", "semantik", "Landing page toko kopi", "Bab 1–5: struktur, teks & daftar, link & gambar, form, semantik",
  "Toko kopi lokal meminta landing page sederhana. Kamu membangunnya bertahap: kerangka dan navigasi, katalog produk, lalu form pesanan.",
  [dict(judul="Kerangka & navigasi",
     soal="Buat halaman lengkap (DOCTYPE, <code>lang=\"id\"</code>, charset, title) dengan <code>&lt;header&gt;</code> berisi <code>&lt;h1&gt;</code> dan <code>&lt;nav&gt;</code> berisi 3 link: <code>#produk</code>, <code>#tentang</code>, <code>#pesan</code>; lalu <code>&lt;main&gt;</code> dan <code>&lt;footer&gt;</code>.",
     solusi=dok('  <header>\n    <h1>Kopi Kenar</h1>\n    <nav>\n      <ul>\n        <li><a href="#produk">Produk</a></li>\n        <li><a href="#tentang">Tentang</a></li>\n        <li><a href="#pesan">Pesan</a></li>\n      </ul>\n    </nav>\n  </header>\n  <main>\n  </main>\n  <footer>© 2026 Kopi Kenar</footer>', judul="Kopi Kenar"),
     awal=AWAL_KOSONG,
     tes=[("Halaman lengkap: doctype, lang=\"id\", charset, title", "!!d.doctype && d.documentElement.lang === 'id' && !!$('meta[charset]') && d.title.trim().length > 0"),
          ("header berisi h1 dan nav", "!!$('header h1') && !!$('header nav')"),
          ("nav punya link ke #produk, #tentang, #pesan", "['#produk', '#tentang', '#pesan'].every(h => $('nav a[href=\"' + h + '\"]'))"),
          ("Ada satu main dan satu footer", "$$('main').length === 1 && $$('footer').length === 1")],
     petunjuk=["Gabungkan bab Struktur (kerangka) dan Semantik (header/nav/main/footer).", "Link internal: href=\"#produk\" dan seterusnya; tujuannya dibuat di bagian B dan C."],
     jelas="Kerangka semantik membuat bagian B dan C tinggal 'mengisi' main."),
   dict(judul="Katalog produk",
     soal="Di dalam main, tambahkan <code>&lt;section id=\"produk\"&gt;</code> dengan <code>&lt;h2&gt;</code> dan <b>3</b> <code>&lt;article&gt;</code> produk. Setiap article berisi <code>&lt;img&gt;</code> beralt, <code>&lt;h3&gt;</code> nama, dan <code>&lt;p class=\"harga\"&gt;</code> berisi \"Rp\". Tambahkan juga <code>&lt;section id=\"tentang\"&gt;</code> dengan <code>&lt;h2&gt;</code> dan daftar <code>&lt;ul&gt;</code> 3 keunggulan.",
     solusi=dok('  <header>\n    <h1>Kopi Kenar</h1>\n    <nav>\n      <ul>\n        <li><a href="#produk">Produk</a></li>\n        <li><a href="#tentang">Tentang</a></li>\n        <li><a href="#pesan">Pesan</a></li>\n      </ul>\n    </nav>\n  </header>\n  <main>\n    <section id="produk">\n      <h2>Produk</h2>\n      <article><img src="a.jpg" alt="Kopi susu gula aren"><h3>Kopi Susu</h3><p class="harga">Rp 18.000</p></article>\n      <article><img src="b.jpg" alt="Es teh manis"><h3>Es Teh</h3><p class="harga">Rp 6.000</p></article>\n      <article><img src="c.jpg" alt="Roti bakar cokelat"><h3>Roti Bakar</h3><p class="harga">Rp 15.000</p></article>\n    </section>\n    <section id="tentang">\n      <h2>Tentang kami</h2>\n      <ul><li>Biji kopi lokal</li><li>Harga mahasiswa</li><li>Buka sampai malam</li></ul>\n    </section>\n  </main>\n  <footer>© 2026 Kopi Kenar</footer>', judul="Kopi Kenar"),
     awal=AWAL_KOSONG,
     tes=[("Ada section#produk dengan h2", "!!$('main section#produk h2')"),
          ("section#produk berisi 3 article", "$$('#produk article').length === 3"),
          ("Setiap article punya img beralt, h3, dan p.harga berisi Rp", "$$('#produk article').length === 3 && $$('#produk article').every(a => a.querySelector('img') && (a.querySelector('img').getAttribute('alt') || '').trim() && a.querySelector('h3') && a.querySelector('p.harga') && /Rp/.test(a.querySelector('p.harga').textContent))"),
          ("Ada section#tentang dengan h2 dan ul 3 item", "!!$('section#tentang h2') && !!$('#tentang ul') && $('#tentang ul').children.length === 3"),
          ("Kerangka bagian A tetap utuh", "!!$('header nav') && $$('main').length === 1 && !!$('footer')")],
     petunjuk=["Tambahkan isi di dalam <main> yang sudah ada, jangan membuat main kedua.", "Satu article = satu kartu produk: img, h3, p.harga."],
     jelas="id pada section membuat link navigasi bagian A bekerja. Setiap kartu memakai struktur yang sama, siap diberi gaya CSS nanti."),
   dict(judul="Form pesanan",
     soal="Tambahkan <code>&lt;section id=\"pesan\"&gt;</code> berisi form: input nama (required), input email (<code>type=\"email\"</code>, required), <code>&lt;select&gt;</code> produk berisi 3 option sesuai produkmu, input jumlah <code>type=\"number\"</code> dengan <code>min=\"1\"</code>, textarea catatan, semuanya berlabel, dan tombol submit.",
     solusi=dok('  <header>\n    <h1>Kopi Kenar</h1>\n    <nav>\n      <ul>\n        <li><a href="#produk">Produk</a></li>\n        <li><a href="#tentang">Tentang</a></li>\n        <li><a href="#pesan">Pesan</a></li>\n      </ul>\n    </nav>\n  </header>\n  <main>\n    <section id="produk">\n      <h2>Produk</h2>\n      <article><img src="a.jpg" alt="Kopi susu gula aren"><h3>Kopi Susu</h3><p class="harga">Rp 18.000</p></article>\n      <article><img src="b.jpg" alt="Es teh manis"><h3>Es Teh</h3><p class="harga">Rp 6.000</p></article>\n      <article><img src="c.jpg" alt="Roti bakar cokelat"><h3>Roti Bakar</h3><p class="harga">Rp 15.000</p></article>\n    </section>\n    <section id="tentang">\n      <h2>Tentang kami</h2>\n      <ul><li>Biji kopi lokal</li><li>Harga mahasiswa</li><li>Buka sampai malam</li></ul>\n    </section>\n    <section id="pesan">\n      <h2>Pesan sekarang</h2>\n      <form>\n        <label for="nama">Nama</label>\n        <input id="nama" name="nama" required>\n        <label for="email">Email</label>\n        <input id="email" name="email" type="email" required>\n        <label for="produk-pilih">Produk</label>\n        <select id="produk-pilih" name="produk"><option>Kopi Susu</option><option>Es Teh</option><option>Roti Bakar</option></select>\n        <label for="jumlah">Jumlah</label>\n        <input id="jumlah" name="jumlah" type="number" min="1" value="1">\n        <label for="catatan">Catatan</label>\n        <textarea id="catatan" name="catatan"></textarea>\n        <button type="submit">Pesan</button>\n      </form>\n    </section>\n  </main>\n  <footer>© 2026 Kopi Kenar</footer>', judul="Kopi Kenar"),
     awal=AWAL_KOSONG,
     tes=[("Ada section#pesan berisi form", "!!$('section#pesan form')"),
          ("Input nama required dan email type=email required", "$$('#pesan input[required]').length >= 2 && !!$('#pesan input[type=email][required]')"),
          ("Select berisi 3 option", "!!$('#pesan select') && $('#pesan select').options.length === 3"),
          ("Input jumlah type=number min=1", "!!$('#pesan input[type=number][min=\"1\"]')"),
          ("Ada textarea", "!!$('#pesan textarea')"),
          ("Semua kontrol berlabel", SEMUA_BERLABEL),
          ("Ada tombol submit", "!!$('#pesan button[type=submit], #pesan input[type=submit]')"),
          ("Bagian A dan B tetap utuh", "$$('#produk article').length === 3 && !!$('header nav')")],
     petunjuk=["Gabungkan bab Form: setiap input punya id dan label for yang sama.", "type=\"number\" min=\"1\" mencegah jumlah nol atau negatif."],
     jelas="Halaman lengkap ini memakai semua bab 1–5. Di bab CSS, halaman serupa akan kamu beri tata letak dan gaya."),
  ])
